SELECT dbr.id, dbrd.id as detailId, dbr.sku_id as skuId, dbr.sku_no as skuNo, dbr.product_name as productName, dbrd.delivery_sku_id as deliverySkuId, dbrd.delivery_sku_no as deliverySkuNo, dbrd.delivery_product_name as deliveryProductName, dbrd.per_box_qty as perBoxQty, dbrd.invalid_time as invalidTime, dbrd.invalid_status as invalidStatus, dbrd.create_user_id as createUserId, dbrd.create_user_name as createUserName, dbrd.create_time as createTime, dbrd.update_user_id as updateUserId, dbrd.update_user_name as updateUserName, dbrd.update_time as updateTime FROM delivery_box_rule dbr LEFT JOIN delivery_box_rule_detail dbrd on dbr.id = dbrd.main_id WHERE ${params.sqlMap.default}
${params.permissionSql}
order by
${item.field} ${item.sort}
dbr.create_time desc
